/* amirsalmani/label — the eyebrow, section number, status key and source line.
 *
 * Requires tokens.css. Mono is for what a machine would emit (brand.md §3), so
 * this and only this carries indices, keys and attributions. Prose is never
 * mono; metadata is never sans.
 */

.as-label {
  font-family: var(--mono);
  font-size: .7rem;
  font-weight: 500;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
}
.as-label--faint { color: var(--faint); }
